INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001580000','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001580000","revision":1,"targetId":"80000000-0000-4000-8000-000000015800","prompt":"Die Polizei nahm die ___ fest, nachdem die Kamera ihren Diebstahl aufgezeichnet hatte.","instruction":{"en":"Choose the option that completes the German sentence correctly.","de":"Wähle die Option, die den deutschen Satz richtig ergänzt."},"hint":{"en":"She committed the theft shown on the recording.","de":"Sie hat den aufgezeichneten Diebstahl begangen."},"slots":[{"id":"word","label":"Wort","options":[{"id":"0","text":"Zeugin"},{"id":"1","text":"Täterin"},{"id":"2","text":"Verkäuferin"},{"id":"3","text":"Richterin"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"word","optionId":"1"}]}],"explanation":{"en":"A Täterin is a woman who committed the act.","de":"Eine Täterin ist eine Frau, die eine Tat begangen hat."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Polizei nahm die Täterin fest, nachdem die Kamera ihren Diebstahl aufgezeichnet hatte.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical facts apps/web/data/pos/nouns.jsonl:L2346 (5941bde0c899670a402f8eede0dc2081efa6a5504dc198096a7208da985747e4), 2026-10-29; inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
